<?php require_once __DIR__.'/includes/config.php';require_applicant();$s=$pdo->prepare('SELECT * FROM applications WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user_id']]);$apps=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | Ladle Loan</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="form-wrap" style="max-width:1000px"><div class="form-card"><a href="index.php">Ladle Loan</a><h1>Welcome, <?=e($_SESSION['user_name']??'Applicant')?></h1><?php if(isset($_GET['submitted'])):?><div class="notice success">Application submitted. Reference: <b><?=e($_GET['submitted'])?></b></div><?php endif;?><p><a class="btn" href="apply.php">+ New application</a> <a href="logout.php">Logout</a></p><h2>Your applications</h2><div class="table-wrap"><table><tr><th>Reference</th><th>Loan</th><th>Amount</th><th>Status</th><th>Date</th></tr><?php foreach($apps as $a):?><tr><td><?=e($a['reference_no'])?></td><td><?=e($a['loan_type'])?></td><td>₹<?=number_format((float)$a['amount'],2)?></td><td class="status"><?=e($a['status'])?></td><td><?=e($a['created_at'])?></td></tr><?php endforeach;?><?php if(!$apps):?><tr><td colspan="5">No applications yet.</td></tr><?php endif;?></table></div></div></div></body></html>